from typing import Annotated, Union
from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field, Tag, Discriminator


class ApplePie(BaseModel):
    kind: str = Field(default="apple", frozen=True)


class PumpkinPie(BaseModel):
    kind: str = Field(default="pumpkin", frozen=True)


def get_discriminator_value(v):
    if isinstance(v, dict):
        return v.get("kind", "apple")
    return getattr(v, "kind", "apple")


Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]


app = FastAPI()


@app.post("/dessert")
def make_dessert(dessert: Dessert):
    return {"kind": dessert.kind}


client = TestClient(app)

# Test with apple pie
response = client.post("/dessert", json={"kind": "apple"})
print("Apple pie response:", response.status_code, response.json())

# Test with pumpkin pie
response = client.post("/dessert", json={"kind": "pumpkin"})
print("Pumpkin pie response:", response.status_code, response.json())

